SELECT 
  FROM kfs01_remote_view
 WHERE kfs01_company_id = #{companyId}
   AND kfs01_person_nm LIKE #{personName}
   AND kfs01_date BETWEEN #{startDate} AND #{closeDate}

   AND (kfs01_close_time IS NULL OR kfs01_reason IS NULL)

   AND kfs01_date BETWEEN #{startDate} AND #{closeDate}
 ORDER BY kfs01_date, kfs01_start_time, kfs01_person_nm

