UPDATE kfs01_remote_view
   SET kfs01_reason     = #{r.reason},
       kfs01_manager_yn = CASE WHEN #{r.managerYn} THEN 'true' ELSE 'false' END
 WHERE kfs01_remote_view_id = #{r.remoteViewId}
   AND kfs01_company_id = #{companyId}

